struct RideScreen: View {
    @State private var showsShare = false
    var body: some View {
        Button("Поделиться поездкой") { showsShare = true }
            .sheet(isPresented: $showsShare) { ShareRidePanel() }
    }
}
struct ShareRidePanel: View {
    @Environment(\.dismiss) private var dismiss
    var body: some View { Button("Закрыть") { dismiss() } }
}

`dismiss` закрывает ближайший показ, внутри которого прочитан. В коде он прочитан в `RideScreen`, а тот показан push в стеке — «Закрыть» уводит с экрана поездки назад к истории, а не просто убирает панель. Действие надо читать в самой панели: тогда оно закрывает именно sheet.

